/**
 * Sound ladders: for each weak sound, practise it in example words, then in
 * minimal pairs against the sound it's confused with, then in short phrases,
 * then in sentences. Content is generated by scripts/build-ladders.ts.
 * Progress lives in learner.ladders (optional, so older saved state is valid).
 */
import { PHONEME_INDEX, RP_PHONEMES } from '../lib/ipa';
import { mastery } from './rlBandit';
import type { AlignmentResult } from './ipaAligner';
import type { LadderDrill, LadderProgress, LadderStage, LearnerState, Prompt } from '../types';

export interface LadderItem { id: string; text: string; source?: Prompt['source'] }
export interface LadderSet { contrast?: string; words: string[]; pairs: [string, string][]; phrases: LadderItem[]; sentences: LadderItem[] }
export type Ladders = Record<string, LadderSet>;

export const STAGE_NAMES: Record<LadderStage, string> = { 1: 'Words', 2: 'Minimal pairs', 3: 'Short phrases', 4: 'Sentences' };
/** Passes needed to climb from each stage. */
export const WINS_NEEDED: Record<LadderStage, number> = { 1: 2, 2: 2, 3: 2, 4: 1 };
/** Share of the focus sound(s) that must be right for a ladder step to pass: two out of three. */
export const FOCUS_PASS = 0.66;
/** Below this many phonemes heard, Sounds mode starts with a quick check. */
export const CHECK_SEEN = 20;
const WEAK_MASTERY = 0.8;

let cache: Promise<Ladders> | null = null;
export function loadLadders(): Promise<Ladders> {
  cache ??= fetch(`${import.meta.env.BASE_URL}data/ladders.json`).then((r) => {
    if (!r.ok) throw new Error('sound ladders unavailable');
    return r.json() as Promise<{ phonemes: Ladders }>;
  }).then((d) => d.phonemes).catch((e) => { cache = null; throw e; });
  return cache;
}

export function ladderProgress(learner: LearnerState, phoneme: string): LadderProgress {
  return learner.ladders?.[phoneme] ?? { stage: 1, wins: 0, updatedAt: 0 };
}

/** Progress after one turn on a ladder step. Only passes at the current stage count; nothing ever moves back. */
export function advanceLadder(lp: LadderProgress | undefined, drill: LadderDrill, passed: boolean, now: number): LadderProgress {
  const base: LadderProgress = lp ?? { stage: 1, wins: 0, updatedAt: now };
  if (base.stage === 5 || !passed || drill.stage !== base.stage) return { ...base, updatedAt: now };
  const wins = base.wins + 1;
  if (wins < WINS_NEEDED[base.stage]) return { ...base, wins, updatedAt: now };
  return { stage: (base.stage + 1) as LadderStage | 5, wins: 0, updatedAt: now };
}

/** True while too few sounds have been heard to know which ones are weak. */
export function needsCheck(learner: LearnerState): boolean {
  return learner.confusion.counts.filter((c) => c > 0).length < CHECK_SEEN;
}

/** Sounds worth a ladder, weakest first (heard a few times, below mastery, ladder not finished). */
export function weakSounds(learner: LearnerState, ladders: Ladders): string[] {
  return RP_PHONEMES
    .filter((p) => ladders[p] && (learner.confusion.counts[PHONEME_INDEX.get(p) ?? -1] ?? 0) >= 3)
    .map((p) => ({ p, m: mastery(learner.confusion, p) }))
    .filter((x) => x.m < WEAK_MASTERY && learner.ladders?.[x.p]?.stage !== 5)
    .sort((a, b) => a.m - b.m)
    .map((x) => x.p);
}

/** Which sound to practise: a requested one, else the ladder in progress, else the weakest sound. */
export function pickLadderSound(learner: LearnerState, ladders: Ladders, focus?: string | null): string | null {
  if (focus && ladders[focus]) return focus;
  const active = Object.entries(learner.ladders ?? {})
    .filter(([p, lp]) => lp.stage !== 5 && ladders[p])
    .sort((a, b) => b[1].updatedAt - a[1].updatedAt);
  if (active.length) return active[0][0];
  return weakSounds(learner, ladders)[0] ?? null;
}

const take = <T>(xs: T[], n: number, from: number) => Array.from({ length: Math.min(n, xs.length) }, (_, i) => xs[(from + i) % xs.length]);
const cap = (w: string) => w[0].toUpperCase() + w.slice(1);
/** One word per sentence, so each is said on its own with a full falling tone. */
const sentence = (xs: string[]) => xs.map((w) => `${cap(w)}.`).join(' ');

/** The practice prompt for a sound at a stage. `seed` varies which items are used. */
export function ladderPrompt(phoneme: string, set: LadderSet, stage: LadderStage, seed: number): Prompt {
  const words = (k: number) => ({ content: 'words' as const, text: sentence(take(set.words, 3, k * 3)), title: `Words with /${phoneme}/` });
  let step: { content: LadderDrill['content']; text: string; title: string; item?: LadderItem; contrast?: string };
  if (stage === 1) step = words(seed);
  else if (stage === 2) {
    step = set.pairs.length && set.contrast
      ? { content: 'pairs', text: take(set.pairs, 3, seed * 3).map((p) => `${cap(p[0])}, ${p[1]}.`).join(' '), title: `/${phoneme}/ or /${set.contrast}/?`, contrast: set.contrast }
      : { ...words(seed + 1), title: `More words with /${phoneme}/` };
  } else {
    const pool = stage === 4 && set.sentences.length ? set.sentences : set.phrases.length ? set.phrases : null;
    const item = pool?.[seed % pool.length];
    step = item ? { content: stage === 4 && set.sentences.length ? 'sentence' : 'phrase', text: item.text, title: `/${phoneme}/ in ${stage === 4 && set.sentences.length ? 'a sentence' : 'a phrase'}`, item } : words(seed);
  }
  const n = step.text.split(/\s+/).length;
  return {
    id: `ld:${phoneme}:${stage}:${step.item?.id ?? step.text.toLowerCase().replace(/[^a-z]+/g, '-')}`,
    tier: 1,
    mode: 'shadow',
    category: 'ladder',
    title: step.title,
    text: step.text,
    reference: step.text,
    targetVocab: [],
    timeLimitSec: Math.max(6, Math.round(n * 0.8 + 5)),
    phonemes: [phoneme],
    ...(step.item?.source ? { source: step.item.source } : {}),
    drill: { kind: 'ladder', phoneme, stage, content: step.content, ...(step.contrast ? { contrast: step.contrast } : {}) },
  };
}

/** How many of the focus sounds were said right. */
export function focusAccuracy(a: AlignmentResult, focus: string[]): { hit: number; total: number } {
  let hit = 0, total = 0;
  for (const pair of a.pairs) {
    if (!pair.target || !focus.includes(pair.target.p)) continue;
    total++;
    if (pair.kind === 'match') hit++;
  }
  return { hit, total };
}

/** Merge two devices' ladders: the further-along ladder wins; at the same stage, the more recent one. */
export function mergeLadders(a: LearnerState['ladders'], b: LearnerState['ladders']): LearnerState['ladders'] {
  if (!a && !b) return undefined;
  const out: Record<string, LadderProgress> = { ...(b ?? {}) };
  for (const [p, lp] of Object.entries(a ?? {})) {
    const o = out[p];
    if (!o || lp.stage > o.stage || (lp.stage === o.stage && lp.updatedAt >= o.updatedAt)) out[p] = lp;
  }
  return out;
}
